INSERT INTO public.cached_botanical_records (scientific_name, perenual_id, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, is_perenual_enriched) VALUES ('Digitalis FOXLIGHT RUBY GLOW', 2483, 'foxglove', 6.0, 7.5, true, '{Seeds,Division}', true, '{"id": 2483, "genus": "Digitalis", "family": "Plantaginaceae", "hybrid": null, "variety": null, "cultivar": null, "authority": null, "other_name": [], "subspecies": null, "common_name": "foxglove", "default_image": null, "scientific_name": ["Digitalis FOXLIGHT RUBY GLOW"], "species_epithet": "FOXLIGHT"}', '2026-06-02 01:40:30.760383+00', 'All parts of the plant contain cardiac glycosides (cardenolides), particularly digitalin. Ingestion by pets can cause serious cardiac arrhythmias, gastrointestinal distress, and potentially fatal heart failure. Even small amounts are dangerous.', 'Average', '{part_shade,full_sun}', 'Biennial', NULL, false);
INSERT INTO public.cached_botanical_records (scientific_name, perenual_id, common_name, ideal_min_ph, ideal_max_ph, is_toxic_to_pets, propagation_methods, is_ai_enriched, raw_api_payload, cached_at, toxicity_notes, watering, sunlight, cycle, plant_type, is_perenual_enriched) VALUES ('Digitalis purpurea ''Sutton''s Apricot''', 2493, 'common foxglove', 6.0, 7.5, true, '{Seeds}', true, '{"id": 2493, "genus": "Digitalis", "family": "Plantaginaceae", "hybrid": null, "variety": null, "cultivar": "Sutton", "authority": null, "other_name": [], "subspecies": null, "common_name": "common foxglove", "default_image": null, "scientific_name": ["Digitalis purpurea ''Sutton''s Apricot''"], "species_epithet": "purpurea"}', '2026-06-02 01:40:30.922554+00', 'All parts of Digitalis purpurea contain cardiac glycosides (digitalis) which are highly toxic if ingested by pets and humans. Toxicity causes gastrointestinal upset, cardiac arrhythmias, and potentially fatal effects.', 'Average', '{part_shade,full_sun}', 'Biennial', NULL, false);
